<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import DashboardRequestsTable from '@/components/DashboardRequestsTable.vue';
import DashboardFooter from '@/components/DashboardFooter.vue';
import RequestProgress from '@/components/RequestProgress.vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { api, errorMessage } from '@/api/client';
import { useAuth } from '@/stores/auth';
import type { AlumniDashboard, ApiResponse } from '@/types/api';
const { user } = useAuth();
const data = ref<AlumniDashboard | null>(null), loading = ref(true), busy = ref(false), error = ref(''), notice = ref(''), storyOpen = ref(false);
const story = reactive({ title: '', content: '', image: '' });
const requestTotal = computed(() => data.value?.requestCounts.reduce((total, row) => total + row._count._all, 0) ?? 0);
const latestRequest = computed(() => data.value?.requests.find(item => !['REJECTED', 'COMPLETED'].includes(item.status)) ?? data.value?.requests[0]);
const date = (value?: string | null) => value ? new Date(value).toLocaleDateString() : '—';
const label = (value: string) => value.replace(/_/g, ' ');
async function load() { loading.value = true; error.value = ''; try { data.value = (await api.get<ApiResponse<AlumniDashboard>>('/alumni/dashboard')).data.data; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function submitStory() { busy.value = true; error.value = ''; notice.value = ''; try { await api.post('/stories', { title: story.title, content: story.content, image: story.image || undefined }); Object.assign(story, { title: '', content: '', image: '' }); storyOpen.value = false; notice.value = 'Story submitted for administrator review.'; await load(); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load);
</script>
<template><DashboardLayout><section class="mx-auto max-w-[1280px] space-y-6 p-4 md:p-6"><div class="grid gap-4 lg:grid-cols-12"><header class="relative flex min-h-[240px] flex-col justify-between overflow-hidden rounded-lg bg-primary-container p-8 text-white lg:col-span-8"><div class="relative z-10"><h1 class="mb-2 text-h1">Welcome back, {{ data?.profile?.fullName?.split(' ')[0] || user?.email }}.</h1><p class="max-w-md text-body-md text-on-primary-container">Your contribution to the Gray D. Allison legacy continues here. Stay updated with your alma mater and manage your professional documents with ease.</p></div><div class="relative z-10 mt-6 flex flex-wrap gap-4"><RouterLink to="/requests/new" class="rounded bg-white px-6 py-2 text-label-sm text-primary hover:bg-slate-100">Apply for Documents</RouterLink><RouterLink to="/alumni" class="rounded border border-white/30 px-6 py-2 text-label-sm hover:bg-white/10">View Alumni Network</RouterLink></div><span aria-hidden="true" class="material-symbols-outlined pointer-events-none absolute -bottom-10 -right-10 text-[240px] text-white/10">shield</span></header><div class="grid gap-4 lg:col-span-4"><RouterLink v-for="action in [{ to: '/stories/mine', icon: 'share', title: 'Share Success Story', note: 'Inspire current students with your professional journey.' }, { to: '/requests/new?type=TRANSCRIPT', icon: 'description', title: 'Request Transcript', note: 'Access your educational and career document services.' }]" :key="action.to" :to="action.to" class="group rounded-lg border border-slate-200 bg-white p-6 hover:border-primary/30"><div class="mb-4 flex items-center justify-between"><span aria-hidden="true" class="material-symbols-outlined rounded p-2" :class="action.icon === 'share' ? 'bg-tertiary-container text-tertiary-fixed-dim' : 'bg-secondary-container text-on-secondary-container'">{{ action.icon }}</span><span aria-hidden="true" class="material-symbols-outlined text-slate-300 group-hover:text-primary">arrow_forward</span></div><h2 class="mb-1 text-lg font-semibold text-primary">{{ action.title }}</h2><p class="text-caption text-on-surface-variant">{{ action.note }}</p></RouterLink></div></div><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><p v-if="loading" role="status">Loading your dashboard…</p><button v-if="error" class="secondary-button" @click="load">Try again</button><template v-if="data && !loading"><section class="space-y-6 rounded-lg border border-slate-200 bg-white p-6"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="flex items-center gap-2 text-xl font-semibold text-primary"><span aria-hidden="true" class="material-symbols-outlined">track_changes</span>Active Document Request Status</h2><span v-if="latestRequest" class="max-w-full break-all rounded bg-surface-container-high px-3 py-1 text-caption text-primary">ID: {{ latestRequest.id }}</span></div><RequestProgress v-if="latestRequest" :status="latestRequest.status"/><p v-else class="text-sm text-secondary">No document requests yet. Submit a request to track its progress here.</p><p v-if="latestRequest?.adminNote" class="whitespace-pre-wrap text-sm">Registrar: {{ latestRequest.adminNote }}</p></section><div class="grid items-start gap-6 lg:grid-cols-12"><DashboardRequestsTable :requests="data.requests" class="lg:col-span-8"/><section class="space-y-6 rounded-lg border border-slate-200 bg-white p-6 lg:col-span-4"><div class="flex items-center justify-between"><h2 class="text-xl font-semibold text-primary">Upcoming Events</h2><RouterLink to="/events" aria-label="View all events"><span aria-hidden="true" class="material-symbols-outlined text-slate-400">event</span></RouterLink></div><RouterLink v-for="event in data.events" :key="event.id" :to="`/events/${event.id}`" class="group flex gap-4"><div class="flex h-14 w-12 shrink-0 flex-col items-center justify-center rounded border border-slate-100 bg-surface-container text-primary group-hover:bg-primary-container group-hover:text-white"><span class="text-[10px] font-black uppercase">{{ new Date(event.eventDate).toLocaleDateString('en', { month: 'short' }) }}</span><span class="text-xl font-black">{{ new Date(event.eventDate).getDate() }}</span></div><div><h3 class="text-label-sm text-primary">{{ event.title }}</h3><p class="mt-1 text-caption text-on-surface-variant">{{ event.eventLocation || 'Location to be confirmed' }}<span v-if="event.eventTime"> · {{ event.eventTime }}</span></p></div></RouterLink><p v-if="!data.events.length" class="text-sm text-secondary">No upcoming events are published.</p></section></div><details class="rounded-lg border border-slate-200 bg-white p-6"><summary class="cursor-pointer text-label-sm text-primary">Membership, profile and alumni updates</summary><div class="mt-6 space-y-6"><div class="grid gap-5 md:grid-cols-3"><section class="space-y-3 border bg-white p-6"><h2 class="text-lg font-semibold">Membership</h2><template v-if="data.membership"><p class="font-bold text-emerald-700">{{ data.membership.status }} · {{ data.membership.activatedAt ? 'Activated' : 'Awaiting activation' }}</p><p class="break-all text-xs">{{ data.membership.reference }}</p><p class="text-sm">Approved {{ date(data.membership.reviewedAt) }}</p></template><p v-else>{{ user?.role === 'ADMIN' ? 'Administrator account' : 'Membership record unavailable' }}</p></section><section class="space-y-3 border bg-white p-6"><h2 class="text-lg font-semibold">Profile completion</h2><p class="text-3xl font-bold">{{ data.profileCompletion.percent }}%</p><progress :value="data.profileCompletion.percent" max="100" class="w-full" aria-label="Profile completion"></progress><p class="text-sm">{{ data.profileCompletion.completed }} of {{ data.profileCompletion.total }} fields complete</p><RouterLink to="/profile" class="underline">Complete profile</RouterLink></section><section class="space-y-3 border bg-white p-6"><h2 class="text-lg font-semibold">My document requests</h2><p class="text-3xl font-bold">{{ requestTotal }}</p><p v-for="count in data.requestCounts" :key="count.status" class="text-sm">{{ label(count.status) }}: {{ count._count._all }}</p><RouterLink to="/requests" class="underline">View request history</RouterLink></section></div>
<div class="grid items-start gap-6 lg:grid-cols-2"><section class="space-y-4 border bg-white p-6"><h2 class="text-h2">Published announcements</h2><details v-for="post in data.announcements" :key="post.id" class="border-t pt-4"><summary class="cursor-pointer font-semibold">{{ post.title }}<time class="mt-1 block text-xs font-normal text-secondary">{{ date(post.publishedAt) }}</time></summary><p class="mt-3 whitespace-pre-wrap">{{ post.content }}</p></details><p v-if="!data.announcements.length" class="text-secondary">No announcements have been published.</p></section><section class="space-y-4 border bg-white p-6"><h2 class="text-h2">Upcoming events</h2><article v-for="event in data.events" :key="event.id" class="space-y-2 border-t pt-4"><h3 class="font-semibold">{{ event.title }}</h3><p class="text-sm">{{ date(event.eventDate) }}<span v-if="event.eventTime"> · {{ event.eventTime }}</span></p><p v-if="event.eventLocation" class="text-sm">{{ event.eventLocation }}</p><p v-if="event.audience" class="text-xs text-secondary">{{ event.audience }}</p><p class="whitespace-pre-wrap text-sm">{{ event.content }}</p></article><p v-if="!data.events.length" class="text-secondary">No upcoming events are published.</p></section></div>
<section class="space-y-5 border bg-white p-6"><RouterLink to="/stories/mine" class="underline">Manage all my stories</RouterLink><div class="flex flex-wrap items-center justify-between gap-4"><h2 class="text-h2">My recent alumni stories</h2><button class="primary-button" @click="storyOpen = !storyOpen">{{ storyOpen ? 'Close story form' : 'Submit a story' }}</button></div><form v-if="storyOpen" class="space-y-4 border p-5" @submit.prevent="submitStory"><label for="story-title" class="field-label">Story title</label><input id="story-title" v-model.trim="story.title" class="field-input" required minlength="3" maxlength="200"><label for="story-content" class="field-label">Your story</label><textarea id="story-content" v-model.trim="story.content" class="field-input" required maxlength="20000" rows="5"></textarea><label for="story-photo" class="field-label">Image URL (optional)</label><input id="story-photo" v-model.trim="story.image" class="field-input" type="url" maxlength="2000"><button class="primary-button" :disabled="busy">{{ busy ? 'Submitting…' : 'Submit for review' }}</button></form><details v-for="post in data.stories" :key="post.id" class="border-t pt-4"><summary class="cursor-pointer font-semibold">{{ post.title }} <span class="ml-2 text-xs font-normal text-secondary">{{ post.isPublished ? 'Published' : 'Awaiting administrator review' }}</span></summary><p class="mt-3 whitespace-pre-wrap">{{ post.content }}</p></details><p v-if="!data.stories.length" class="text-secondary">You have not submitted a story yet.</p></section>
</div></details></template><DashboardFooter/></section></DashboardLayout></template>
